const $=s=>document.querySelector(s),app=$('#app'),audio=new ArcadeAudio({onState:state=>{const control=$('#sound');if(control){control.dataset.audioState=state.state;control.dataset.playCount=state.playCount;if(state.effect)control.dataset.lastEffect=state.effect;}}}),juice=new GameJuice(app),letters=['A','B','C','D'];
let storage;try{storage=window.localStorage}catch{storage={getItem:()=>null,setItem:()=>{throw Error('Unavailable')}}}
let profile=loadProfile(storage,questions),run=profile.run,view='title',paused=false,deadline=0,timer=null,lastSavedSecond=-1,filter='all',env=0,storageOK=true;
const combat=new CombatDirector(),director=new JourneyDirector(),answerReveal=new AnswerReveal(document),armorReveal=new AnswerReveal(document);
let pendingCombatHUD=null,heldAnimations=[],pauseFocus=null,encounter=null,medalAwards=[];
let nameDraft=profile.nickname,collectionDraft=null,studyPathDraft=null;
bindChallengeCopy(app);
bindSupport(app);
const cloud=bindCloud({root:app,storage,bank:questions,getProfile:()=>profile,applyProfile:restored=>{profile=restored;run=profile.run;medalAwards=[];pendingCombatHUD=null;setView('title');}});
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
$('#game-version').textContent=`VERSION ${gameVersion}`;
const number=n=>Math.floor(n).toLocaleString('en-US');
const button=(label,action,cls='button',disabled=false)=>`<button class="${cls}" data-action="${action}" ${disabled?'disabled':''}>${label}</button>`;
function judah(completed=0,pose='idle',caption=true){return drawJudah(Math.max(completed,profile.bestCompleted),pose,caption,profile.armor.unlocked,wardrobeFor(profile.bestCompleted,profile.mastery.legacyCompleted))}
function legacyHonor(){const old=legacyRankFor(profile.mastery.legacyCompleted);return old.name==='Novice'?'':`<p class="fine-print legacy-honor">LEGACY HONOR · ${esc(rankLabel(old))} under the earlier milestones. Retained wardrobe access; current rank follows the new completed-level milestones.</p>`}
function claimArmor(){const id=profile.armor.pending[0];if(!acknowledgeArmor(profile,id))return;armorReveal.close();persist();render()}
function persist(){if(run)captureProgress(profile,run);storageOK=saveProfile(storage,profile);if(storageOK&&typeof cloud!=='undefined')cloud.localChanged();const msg=$('#storage-warning');if(msg)msg.hidden=storageOK;}
function music(){audio.configure(profile.settings.sound,profile.settings.music,view==='game'&&!paused&&run?.status==='playing'||view==='title'||view==='settings'||view==='name-entry'||view==='collection'||view==='study-path'||view==='encounter'&&!paused&&!document.hidden||view==='journey'&&!paused&&!document.hidden)}
function stopClock(){clearInterval(timer);timer=null;deadline=0}
function clock(){if(view!=='game'||paused||run?.status!=='playing')return;run.remaining=Math.max(0,(deadline-Date.now())/1000);const seconds=Math.ceil(run.remaining);$('.question-panel')?.classList.toggle('time-urgent',seconds<=10);if($('#clock')){$('#clock').textContent=String(seconds).padStart(2,'0');$('#clock').classList.toggle('danger',seconds<=10)}if($('#time-fill'))$('#time-fill').style.width=`${Math.min(100,run.remaining/levelConfig(run.level).seconds*100)}%`;if(seconds!==lastSavedSecond){lastSavedSecond=seconds;persist()}if(run.remaining===0)choose(-1);}
function startClock(){stopClock();if(view!=='game'||paused||run?.status!=='playing')return;deadline=Date.now()+run.remaining*1000;timer=setInterval(clock,150)}
function setView(next){director.cancel();stopClock();view=next;paused=false;render();startClock();music();window.scrollTo({top:0,behavior:'instant'})}
function retry(){if(!retryLevel(run,questions))return;persist();audio.unlock();audio.effect('start');beginEncounter();juice.enter('question')}
function start(){nameDraft=profile.nickname;collectionDraft=null;studyPathDraft=null;setView('collection');$('#screen-title')?.focus()}
function chooseCollection(id){if(view!=='collection'||!validCollection(id))return;if(collectionDraft!==id)studyPathDraft=null;collectionDraft=id;setView('study-path');$('#screen-title')?.focus()}
function chooseStudyPath(id){if(view!=='study-path'||!validCollection(collectionDraft)||!validStudyPath(id))return;studyPathDraft=id;openPlayerName()}
// Future character selection can be inserted at this single flow boundary.
function openPlayerName(){setView('name-entry');$('#nickname')?.focus({preventScroll:true});$('#nickname')?.select()}
function cancelStart(){if(view==='name-entry'){setView('study-path');$('#screen-title')?.focus();return}if(view==='study-path'){setView('collection');$('#screen-title')?.focus();return}nameDraft=profile.nickname;collectionDraft=null;studyPathDraft=null;setView('title');$('[data-action="start"]')?.focus({preventScroll:true})}
function confirmPlayerName(){if(view!=='name-entry'||!validCollection(collectionDraft)||!validStudyPath(studyPathDraft))return;beginNewGame($('#nickname')?.value??nameDraft)}
// Future character selection can follow name confirmation here without changing
// run creation, saves or the title/Continue routes. Judah remains the only hero.
function beginNewGame(nickname){if(run&&run.status!=='gameover'&&!confirm('Start a new run? Your saved run will be replaced.'))return;profile.nickname=cleanNickname(nickname);medalAwards=[];run=createRun(questions,profile.nickname,Math.random,collectionDraft,studyPathDraft);persist();audio.unlock();audio.effect('start');beginEncounter()}
function choose(choice){
 if(view!=='game'||!run||paused||run.status!=='playing'||combat.active)return;
 if(deadline&&Date.now()>=deadline)choice=-1;
 stopClock();const before={score:run.score,streak:run.streak,...combatHealth(run)};if(!submit(run,questions,choice))return;
 medalAwards=creditMasteryAnswer(profile,run,questions);
 pendingCombatHUD=before;
 run.combatPresentation={answer:run.answers.length,complete:false};persist();
 if(pendingBattleDialogue(run)){if(!profile.settings.skipDialogue)return beginBattleDialogue();clearBattleDialogue(run);persist()}
 render(true);music();
 playCombat(before);
}
function playCombat(before){
 const last=run.answers.at(-1);
 combat.start({correct:last.correct,enemyDefeated:combatHealth(run).enemy===0,heroDefeated:!last.correct&&!last.shielded&&run.lives===0,variation:finisherVariation(run.level),reducedMotion:matchMedia('(prefers-reduced-motion: reduce)').matches,
  onFrame:frame=>{paintCombat($('.game-scene'),frame,masteryCompleted(run),profile.armor.unlocked,wardrobeFor(profile.bestCompleted,profile.mastery.legacyCompleted));if(frame.phase==='strike')audio.effect('swordSwing');if(frame.shieldImpact)audio.effect('shieldClang');if(frame.phase==='ground'||frame.phase==='hero-ground'){audio.effect('groundImpact');juice.burst($('.combat-sparks'),8,'gold');}},
  onImpact:()=>{
   pendingCombatHUD=null;
   updateCombatHealth($('.combat-health'),run);
   if($('#hit-count'))$('#hit-count').textContent=String(combatHealth(run).hits);
   const seals=$('.boss-health');if(seals){const gate=gateProgress(run);seals.setAttribute('aria-label',String(10-gate.broken)+' gate seals remaining');seals.querySelector('span').textContent='SEALS SHATTERED '+gate.broken+' / 10';seals.querySelectorAll('i').forEach((seal,i)=>{seal.classList.toggle('broken',i<gate.broken);seal.classList.toggle('breaking',last.correct&&i===gate.broken-1)})}
   $('.game-scene>.symbolic-gate')?.style.setProperty('--gate-power',String(gateProgress(run).broken/10));
   // Commit the visual reward/penalty at impact; the engine and save already own the result.
   const template=document.createElement('template');template.innerHTML=hud();$('.hud')?.replaceWith(template.content.firstElementChild);
   if(last.correct){audio.effect('swordStrike');if(combatHealth(run).enemy===0){audio.effect('finisher');}else if(levelConfig(run.level).boss)audio.effect('heavyImpact');audio.effect('correct',.18)}else audio.effect(last.shielded?'shield':'damage');
   if(!last.correct&&!last.shielded){audio.effect('lifeLost',.2);if(run.lives===0)audio.effect('finisher');}
   juice.answer({...last,score:run.score,streak:run.streak});
   juice.combatNumber($('.game-scene'),combatDamageFeedback(before,combatHealth(run),last));
   juice.burst($('.combat-sparks'),16,last.correct?'gold':'green');
   if(last.correct&&levelConfig(run.level).boss)juice.burst($('.symbolic-gate'),12,'gold');
  },
  onFinish:()=>{run.combatPresentation={answer:run.answers.length,complete:true};persist();if($('#answer-reveal'))answerReveal.open($('#answer-reveal'),proceed);showMedalNotification(medalAwards,audio);medalAwards=[];}
 });
}
function proceed(){if(paused||combat.active||view!=='game'||!run||run.status!=='feedback')return;advance(run,questions);persist();if(pendingBattleDialogue(run))return beginBattleDialogue();render();startClock();music();if(run.status==='levelup'){const perfect=run.answers.every(a=>a.correct);audio.effect(perfect?'perfectVictory':run.lastPromotion?'promotion':'levelComplete');if(levelConfig(run.level).boss)audio.effect('gateOpen',.15)}else audio.effect(run.status==='gameover'?'gameover':'next');if(run.status==='levelup'&&run.flawless?.reward?.type)audio.effect('powerRestored',.18);juice.enter(run.lastPromotion&&run.status==='levelup'?'promotion':'question');if(run.status==='levelup'&&run.flawless?.reward?.type)juice.burst($('.flawless-reward'),12,'gold');if(run.status==='levelup'&&(run.lastPromotion||run.answers.every(a=>a.correct)))juice.burst($('.result-adventure'),24,'gold');$('#screen-title')?.focus()}
function finishJourney(){if(paused||!run||run.status!=='levelup')return;director.cancel();nextLevel(run,questions);persist();beginEncounter();audio.effect(levelConfig(run.level).boss?'gatekeeper':'next');juice.enter();$('#screen-title')?.focus()}
// Untimed, manual introduction. The checkpoint is presentation-only and never advances a quiz.
function beginEncounter(restore=false){
 stopClock();encounter=new EncounterDialogue(run.level,restore?run.dialogue:null);run.dialogue=encounter.checkpoint();persist();
 if(profile.settings.skipDialogue)return finishEncounter();
 setView('encounter');$('#dialogue-next')?.focus();
}
function beginBattleDialogue(){
 stopClock();if(profile.settings.skipDialogue){clearBattleDialogue(run);persist();setView('game');$('#screen-title')?.focus();return}
 const checkpoint=claimBattleDialogue(run);if(!checkpoint){setView('game');$('#screen-title')?.focus();return}
 encounter=new EncounterDialogue(run.level,{level:run.level,step:checkpoint.step},battleExchange(run.level,checkpoint.kind,checkpoint.exchangeId,run));persist();setView('encounter');$('#dialogue-next')?.focus();
}
function finishEncounter(){
 if(!encounter||encounter.done||paused)return;
 if(encounter.kind){encounter.skip();run.battleDialogue.active=null;encounter=null;persist();if(pendingBattleDialogue(run))return beginBattleDialogue();setView('game');$('#screen-title')?.focus();return}
 encounter.skip();run.dialogue=encounter.checkpoint();persist();encounter=null;setView('game');$('#screen-title')?.focus();
}
function advanceDialogue(){
 if(view!=='encounter'||paused||!encounter)return;
 if(encounter.step===1)return finishEncounter();
 encounter.next();if(encounter.kind)run.battleDialogue.active.step=encounter.step;else run.dialogue=encounter.checkpoint();persist();render();$('#dialogue-next')?.focus();
}
function encounterScreen(){if(encounter.kind==='knockout')pendingCombatHUD=previousCombatHUD();return battleScene()+dialogueMarkup(encounter,opponentFor(run.level).name)}
function beginJourney(){if(!run||run.status!=='levelup'||director.active)return;stopClock();if(profile.settings.shortJourneys||matchMedia('(prefers-reduced-motion: reduce)').matches)return finishJourney();view='journey';paused=false;render();music();$('#skip-journey')?.focus();director.start({onPhase:phase=>{const screen=$('.journey-screen');if(!screen)return;screen.dataset.phase=phase.name;$('.journey-hero').innerHTML=judah(run.completed,phase.pose,false);if(phase.name==='arrival')audio.effect((run.level+1)%5===0?'gatekeeper':'select');},onFinish:finishJourney})}
function journeyScreen(){const next=run.level+1,[slug,name]=locationFor(next);return `<section class="journey-screen" data-phase="walk"><p class="kicker">THE NEXT GATE AWAITS</p><h1 id="screen-title" tabindex="-1">${name}</h1><div class="journey-canvas" aria-label="Akobi journeys toward the next Scripture challenge"><div class="journey-plane journey-sky" style="background-image:url('assets/console/journey-${slug}-sky.png')"></div><div class="journey-plane journey-far" style="background-image:url('assets/console/journey-${slug}-far.png')"></div><div class="journey-plane journey-near" style="background-image:url('assets/console/journey-${slug}-near.png')"></div><div class="journey-destination">${symbolicGate()}</div><div class="journey-hero">${judah(run.completed,'walk',false)}</div><div class="journey-intro"><b>LEVEL ${next}</b><span>${next%5===0?'GATEKEEPER CHALLENGE':'NEXT OPPONENT'} · ${opponentFor(next).name}</span></div></div><p class="journey-caption">A brief journey between Scripture challenges. Your question timer has not started.</p>${button('SKIP JOURNEY →','skip-journey','button primary').replace('<button','<button id="skip-journey"')} ${button('TURN OFF FUTURE JOURNEYS','transitions','menu-link')}<p class="fine-print">Escape skips · P pauses. Returning to the game requires Resume.</p></section>`}
// Suspend the live DOM: redrawing here would cancel combat and restart sprite frames.
function releasePause(){if(!paused)closeGuardPause();document.body.classList.remove('app-paused');for(const node of [...app.children,$('header')])node.inert=false;$('.pause-overlay')?.remove();for(const animation of heldAnimations)if(animation.playState==='paused')animation.play();heldAnimations=[]}
function mountPause(){
 if($('.pause-overlay'))return;
 pauseFocus=document.activeElement;answerReveal.close();armorReveal.close();
 heldAnimations=document.getAnimations().filter(a=>a.playState==='running');heldAnimations.forEach(a=>a.pause());
 document.body.classList.add('app-paused');for(const node of [...app.children,$('header')])node.inert=true;
 app.insertAdjacentHTML('beforeend',pauseScreen());$('.pause-overlay').querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>act(b.dataset.action));$('#resume-button')?.focus();
}
function pause(){
 if(paused||!run||!['game','journey','encounter'].includes(view))return;
 if(view==='game'&&run.status==='playing'&&deadline){run.remaining=Math.max(0,(deadline-Date.now())/1000);if(run.remaining===0)choose(-1)}
 stopClock();paused=true;combat.pause();director.pause();juice.pause();persist();mountPause();music();if(!document.hidden)audio.effect('pause');
}
function resume(){if(!paused||document.hidden)return;paused=false;releasePause();combat.resume();director.resume();juice.resume();startClock();music();audio.effect('resume');if($('#armor-reveal'))armorReveal.open($('#armor-reveal'),claimArmor);else if($('#answer-reveal')&&!combat.active)answerReveal.open($('#answer-reveal'),proceed);else if(pauseFocus?.isConnected)pauseFocus.focus();else $('#screen-title')?.focus()}
function power(type){if(view!=='game'||paused||combat.active||run?.status!=='playing')return;if(deadline)run.remaining=Math.max(0,(deadline-Date.now())/1000);if(!usePower(run,questions,type))return;audio.effect('power');persist();render();startClock()}
function retire(){if(!confirm('End this run and record its current score on this device?'))return;stopClock();breakFlawless(run);run.status='gameover';run.endedAt=new Date().toISOString();paused=false;persist();render();music();audio.effect('gameover')}
function activeEnvironment(){const unlocked=environments.filter(e=>profile.bestCompleted>=e.unlock);return Math.min(env,unlocked.length-1)}
function hud(){const shown=pendingCombatHUD||run,rank=rankFor(masteryCompleted(run)),progress=rankProgress(masteryCompleted(run)),mult=Math.min(5,1+Math.floor(shown.streak/3));return `<div class="hud"><div><small>PLAYER</small><strong>${esc(run.nickname)}</strong></div><div><small>SCORE</small><strong id="score-value" class="gold">${number(shown.score).padStart(6,'0')}</strong></div><div><small>LEVEL</small><strong>${String(run.level).padStart(2,'0')}</strong></div><div><small>LIVES</small><strong class="hearts" aria-label="${shown.lives} lives remaining">${'♥'.repeat(shown.lives)}<span>${'♡'.repeat(MAX_LIVES-shown.lives)}</span></strong></div><div><small>STREAK ${shown.streak}</small><strong class="cyan hud-combo">×${mult}</strong></div></div><div class="rank-strip"><span>✦ ${esc(rankLabel(rank))}</span><span>${progress.remaining} level${progress.remaining===1?'':'s'} to promotion</span><progress aria-label="Progress to next promotion" value="${progress.value}" max="${progress.max}"></progress>${flawlessMarkup(run)}</div>`}
function titleScreen(){const rank=rankFor(profile.bestCompleted);return `<section class="title-screen"><div class="personal-bar"><span>PERSONAL BEST <b>${number(profile.bestScore)}</b></span><span>HIGHEST RANK <b>${esc(rankLabel(rank))}</b></span><span>LEVELS CLEARED <b>${profile.bestCompleted}</b></span></div><div class="broadcast"><i></i> ARCADE EDITION <span>EST. IN THE WORD • VOL. 02</span></div><div class="title-art kingdom-title">${landscape(activeEnvironment())}<div class="kingdom-castle" aria-hidden="true"><div class="world-plane"><img class="world-raster" src="assets/console/kingdom-castle.svg" width="640" height="280" alt=""></div></div>${judah(profile.bestCompleted)}<div class="floating-sword">${sword}</div><div class="title-logo"><h1 aria-label="Kingdom Race The Lion’s Gate"><span class="kingdom-name">Kingdom Race</span> <span class="gate-name"><span>The Lion’s</span> <span>Gate</span></span></h1></div><span class="art-caption">${environments[activeEnvironment()].name.toUpperCase()}</span></div><div class="title-menu"><p class="title-scripture"><span>Help Akobi take the Kingdom.</span><cite>Daniel 7:18</cite></p>${button(run?'▶ &nbsp; NEW GAME':'▶ &nbsp; PRESS START','start','button primary press-start')}${canRetryLevel(run)?button(`RETRY · LEVEL ${run.level}`,'retry-level','button continue'):run&&run.status!=='gameover'?button(`CONTINUE · LEVEL ${run.level}`,'continue','button continue'):''}<div class="menu-links">${button('HALL OF MASTERS','hall','menu-link')}${button('HOW TO PLAY','guide','menu-link')}${button('THE ARMORY','armory','menu-link')}${button('SETTINGS','settings','menu-link')}${button('TROPHY ROOM','trophies','menu-link')}<button type="button" class="menu-link support-link" data-support-open>SUPPORT R2G2</button></div></div></section>`}
function previousCombatHUD(){const last=run.answers.at(-1);return {score:run.score-last.earned,streak:run.streak,...combatHealth({...run,answers:run.answers.slice(0,-1)}),lives:run.lives+(!last.correct&&!last.shielded?1:0)}}
function restoreCombatPresentation(){
 if(view!=='game'||paused||run?.status!=='feedback')return false;
 const last=run.answers.at(-1),h=combatHealth(run);
 if(run.combatPresentation?.answer===run.answers.length&&!run.combatPresentation.complete){
  const before=previousCombatHUD();
  pendingCombatHUD=before;render(true);playCombat(before);return true;
 }
 if(h.enemy===0||h.lives===0)paintCombat($('.game-scene'),{at:1600,phase:h.enemy===0?'defeated':'hero-defeated',enemy:h.enemy===0?4:0,correct:h.enemy===0,finisher:h.enemy===0?'enemy':'judah',heroReady:h.enemy===0,reducedMotion:matchMedia('(prefers-reduced-motion: reduce)').matches},masteryCompleted(run),profile.armor.unlocked,wardrobeFor(profile.bestCompleted,profile.mastery.legacyCompleted));
 return false;
}
function battleScene(){const config=levelConfig(run.level),feedback=run.status==='feedback',last=run.answers.at(-1),gate={...gateProgress(run),...(pendingCombatHUD?{broken:pendingCombatHUD.hits}:{})};return `${hud()}${combatHealthMarkup(run,pendingCombatHUD)}<div class="game-scene ${config.boss?'boss-scene adventure-arena':''}">${landscape(Math.min(environments.length-1,environments.filter(e=>run.completed>=e.unlock).length-1))}${config.boss?symbolicGate(gate):''}<div class="scene-status"><span>${config.boss?'⚔ GATEKEEPER CHALLENGE':'✦ LEVEL '+run.level} <b>${config.boss?'DOUBLE POINTS · CONTEXT CHALLENGE':'THE WORD IS YOUR WEAPON'}</b></span>${judah(run.completed,'ready',false)}${romanSoldier(combatHealth(run,pendingCombatHUD).enemy===0)}<span class="combat-sparks" aria-hidden="true"></span><div class="small-sword">${sword}</div>${config.boss?`<div class="boss-health" aria-label="${10-gate.broken} gate seals remaining"><span>SEALS SHATTERED ${gate.broken} / 10</span><div>${Array.from({length:10},(_,i)=>`<i class="${i<gate.broken?'broken':''} ${feedback&&!pendingCombatHUD&&last.correct&&i===gate.broken-1?'breaking':''}"></i>`).join('')}</div></div>`:''}</div></div>`}
function questionScreen(){const entry=run.queue[run.index],q=questions.find(q=>q.id===entry.id),config=levelConfig(run.level),feedback=run.status==='feedback',last=run.answers.at(-1),gate=gateProgress(run);return `${battleScene()}<section class="question-panel"><div class="question-meta"><span>QUESTION ${run.index+1} · <span id="hit-count">${combatHealth(run,pendingCombatHUD).hits}</span>/10 HITS <b>• ${esc(q.category)}</b>${q.trapType?` <em class="trap-label">${q.trapType.toUpperCase()} TRAP</em>`:''}</span><span class="difficulty">${'◆'.repeat(q.difficulty)}${'◇'.repeat(3-q.difficulty)} <span>${['','FOUNDATION','CHALLENGER','CONTEXT'][q.difficulty]}</span></span><span class="clock">◷ <b id="clock">${Math.ceil(run.remaining)}</b>s</span></div><div class="time-track"><div id="time-fill" style="width:${Math.min(100,run.remaining/config.seconds*100)}%"></div></div><h1 id="screen-title" tabindex="-1">${esc(q.q)}</h1><div class="answers">${entry.order.map((original,i)=>{const hidden=run.eliminated.includes(original);return `<button class="answer ${feedback?(original===q.answer?'correct':original===last.choice?'wrong':'dim'):''} ${hidden?'eliminated':''}" data-answer="${original}" ${feedback||hidden?'disabled':''}><span>${letters[i]}</span><strong>${hidden?'— — —':esc(q.options[original])}</strong><b>${feedback&&original===q.answer?'✓':feedback&&original===last.choice?'×':''}</b></button>`}).join('')}</div><div class="power-row"><span>POWER-UPS <small>2 FLAWLESS LEVELS = RESTORE</small></span>${button(`◈ 50:50 <b>${run.powers.fifty}</b>`,'fifty','power',feedback||!run.powers.fifty||run.eliminated.length>0)}${button(`◷ +15s <b>${run.powers.time}</b>`,'time','power',feedback||!run.powers.time)}${button(`⬡ SHIELD <b>${run.powers.shield}</b>`,'shield','power',feedback||!run.powers.shield||run.shielded)}</div><p class="controls-hint">${run.shielded?'⬡ SHIELD ACTIVE · THE NEXT MISTAKE IS PROTECTED':'CHOOSE AN ANSWER · A–D OR 1–4 · P TO PAUSE'}</p></section>${feedback?answerRev